function sourceReference(path=location.pathname){return 'QM-'+(path==='/'?'HOME':path.replace(/^\/|\/$/g,'').replace(/[^a-z0-9]+/gi,'-').toUpperCase())}
let latestInquirySource='direct-form',sourceCampaign={};
try{const incoming=new URLSearchParams(location.search);for(const key of ['utm_source','utm_medium','utm_campaign','utm_content','utm_term']){const value=incoming.get(key);if(value)sourceCampaign[key]=value.replace(/[^a-z0-9 _.-]/gi,'').slice(0,100)}const prior=JSON.parse(sessionStorage.getItem('qm-campaign')||'{}');sourceCampaign=Object.keys(sourceCampaign).length?sourceCampaign:prior;sessionStorage.setItem('qm-campaign',JSON.stringify(sourceCampaign));latestInquirySource=(incoming.get('qm_source')||'direct-form').replace(/[^a-z0-9_-]/gi,'').slice(0,160)}catch{}
function inquiryAttribution(){return {page:location.pathname,cta:latestInquirySource,reference:sourceReference(),utm:sourceCampaign}}
function tagPageSources(){const reference=sourceReference();document.querySelectorAll('[data-action],a[data-route]').forEach((el,i)=>{const label=(el.dataset.action||el.textContent||'link').trim().toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,70);el.dataset.source=reference+'-'+label;if(el.matches('a[data-route]')){const u=new URL(el.getAttribute('href'),location.origin);u.searchParams.set('qm_source',el.dataset.source);el.setAttribute('href',u.pathname+u.search+u.hash)}});document.querySelectorAll('a[href^="mailto:yiweiinc99@gmail.com"]').forEach(el=>{el.setAttribute('href','mailto:yiweiinc99@gmail.com?subject='+encodeURIComponent('QuickMind enquiry | '+reference)+'&body='+encodeURIComponent('Source page: '+location.pathname+'\nPage reference: '+reference+'\nSource entry: direct-email\nCampaign: '+JSON.stringify(sourceCampaign)))});const label=document.querySelector('#page-source-reference');if(label)label.textContent=(label.dataset.sourceLabel||'Page reference')+': '+reference;measurePage()}
// Anonymous counts stay on this browser only. No form values, email addresses or query strings are recorded.
const engagementKey='qm-engagement-v1';let activePage='',activeStarted=0;
function enabledForMeasurement(){return navigator.doNotTrack!=='1'&&navigator.globalPrivacyControl!==true}
function addMetric(path,key,value=1){if(!enabledForMeasurement())return;path=path==='/products/quickmind-home/'?'/home-product/':path;try{const data=JSON.parse(localStorage.getItem(engagementKey)||'{}');const item=data[path]||{views:0,activeSeconds:0,inquiryClicks:0,internalClicks:0,faqOpens:0,maxScroll:0,emailDrafts:0};if(key==='maxScroll')item[key]=Math.max(item[key],value);else item[key]=(item[key]||0)+value;data[path]=item;localStorage.setItem(engagementKey,JSON.stringify(data))}catch{}}
function flushActive(){if(activePage&&activeStarted){addMetric(activePage,'activeSeconds',Math.min(300,Math.round((Date.now()-activeStarted)/1000)));activeStarted=0}}
function measurePage(){if(activePage===location.pathname)return;flushActive();activePage=location.pathname;addMetric(activePage,'views');activeStarted=document.hidden?0:Date.now()}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action],a[data-route]');if(!el)return;if(['inquiry','clinic','distributor','support'].includes(el.dataset.action)){latestInquirySource=el.dataset.source||sourceReference()+'-inquiry';addMetric(location.pathname,'inquiryClicks')}if(el.matches('a[data-route]')){latestInquirySource=el.dataset.source||'internal-link';addMetric(location.pathname,'internalClicks')}},true);
document.addEventListener('toggle',e=>{if(e.target.tagName==='DETAILS'&&e.target.open&&e.target.closest('.faq'))addMetric(location.pathname,'faqOpens')},true);
document.addEventListener('visibilitychange',()=>{if(document.hidden)flushActive();else if(activePage)activeStarted=Date.now()});window.addEventListener('pagehide',flushActive);window.addEventListener('pageshow',()=>{if(activePage&&!document.hidden&&!activeStarted)activeStarted=Date.now()});window.addEventListener('scroll',()=>{const range=document.documentElement.scrollHeight-window.innerHeight;if(range>0)addMetric(location.pathname,'maxScroll',Math.min(100,Math.round(window.scrollY/range*100)))},{passive:true});
function localInsights(){try{return JSON.parse(localStorage.getItem(engagementKey)||'{}')}catch{return {}}}
